"use client";
import "./spinner.css";

/** The classic spoke spinner, drawn in your text color at any size. */
export function Spinner({
  size = 24,
  label = "Loading",
  className = "",
}: {
  size?: number;
  label?: string;
  className?: string;
}) {
  return (
    <span role="status" aria-label={label} className={`forme-spinner ${className}`} style={{ width: size, height: size }}>
      {Array.from({ length: 8 }, (_, i) => (
        <i key={i} style={{ transform: `rotate(${i * 45}deg)`, animationDelay: `${-0.9 + i * 0.1125}s` }} />
      ))}
    </span>
  );
}

.forme-spinner {
  position: relative;
  display: inline-block;
}
.forme-spinner i {
  position: absolute;
  top: 0;
  left: calc(50% - 6%);
  width: 12%;
  height: 28%;
  border-radius: 99px;
  background: currentColor;
  transform-origin: 50% 178%;
  animation: forme-spinner 0.9s linear infinite;
}
@keyframes forme-spinner {
  from {
    opacity: 1;
  }
  to {
    opacity: 0.15;
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-spinner i {
    animation-duration: 2.4s;
  }
}
